/**
 * gerar-sql-postgres.mjs — Converte os scripts MySQL de database/ para PostgreSQL
 * (npm run sql:postgres).
 *
 * O banco "oficial" do PI 2 é o MySQL/MariaDB do XAMPP (database/01-criacao.sql e
 * 02-carga-dados.sql). A versão publicada na internet usa o PostgreSQL do Neon, que é
 * gratuito. Para não manter dois modelos à mão, este script gera a versão PostgreSQL a
 * partir dos arquivos MySQL, trocando só o que muda entre os dois SGBDs:
 *
 *   MySQL                               PostgreSQL
 *   INT UNSIGNED ... AUTO_INCREMENT  →  INTEGER GENERATED BY DEFAULT AS IDENTITY
 *   BIGINT/INT/TINYINT UNSIGNED      →  BIGINT / INTEGER / SMALLINT
 *   ENUM('a','b')                    →  VARCHAR + CHECK (coluna IN ('a','b'))
 *   DATETIME                         →  TIMESTAMP
 *   REGEXP                           →  ~
 *   COMMENT '...' e ENGINE=InnoDB    →  removidos
 *
 * As tabelas, colunas, chaves e restrições continuam as mesmas.
 */
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const RAIZ = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const ORIGEM = path.join(RAIZ, 'database');
const DESTINO = path.join(RAIZ, 'database', 'postgres');

const AVISO = `-- GERADO por scripts/gerar-sql-postgres.mjs (npm run sql:postgres) a partir da versão MySQL.
-- Não edite à mão: altere o arquivo MySQL correspondente em database/ e gere de novo.
-- Esta é a versão usada no banco publicado (PostgreSQL do Neon).
`;

/** Tabelas com chave numérica automática: a sequência continua depois do maior id carregado. */
const IDENTIDADES = [];

function converterCriacao(sql) {
  const linhas = sql.split(/\r?\n/);
  const saida = [];
  let tabela = null;
  for (let linha of linhas) {
    // Cabeçalho do MySQL: banco e codificação ficam por conta do Neon (UTF-8).
    if (/^(DROP DATABASE|CREATE DATABASE| {2}DEFAULT (CHARACTER|COLLATE)|USE )/.test(linha)) continue;

    const criar = linha.match(/^CREATE TABLE (\w+)/);
    if (criar) tabela = criar[1];

    linha = linha.replace(/\s+COMMENT '(?:[^']|'')*'/g, '');
    linha = linha.replace(/\) ENGINE=InnoDB;/, ');');

    const auto = linha.match(/^(\s*)(\w+)(\s+)(BIGINT|INT) UNSIGNED\s+NOT NULL AUTO_INCREMENT/);
    if (auto) {
      IDENTIDADES.push({ tabela, coluna: auto[2] });
      const tipo = auto[4] === 'BIGINT' ? 'BIGINT' : 'INTEGER';
      linha = linha.replace(
        /(BIGINT|INT) UNSIGNED\s+NOT NULL AUTO_INCREMENT/,
        `${tipo} GENERATED BY DEFAULT AS IDENTITY`
      );
    }
    linha = linha
      .replace(/BIGINT UNSIGNED/g, 'BIGINT')
      .replace(/TINYINT UNSIGNED/g, 'SMALLINT')
      .replace(/\bINT UNSIGNED/g, 'INTEGER')
      .replace(/\bDATETIME\b/g, 'TIMESTAMP')
      .replace(/ REGEXP /g, ' ~ ');

    // ENUM vira texto com CHECK, no fim da definição da coluna.
    const enumeracao = linha.match(/^(\s*)(\w+)(\s+)ENUM\(([^)]*)\)(.*?)(,?)$/);
    if (enumeracao) {
      const [, recuo, coluna, espaco, valores, resto, virgula] = enumeracao;
      const maior = Math.max(...valores.split(',').map((v) => v.trim().length - 2));
      linha = `${recuo}${coluna}${espaco}VARCHAR(${maior})${resto} CHECK (${coluna} IN (${valores}))${virgula}`;
    }
    saida.push(linha);
  }
  const corpo = saida
    .join('\n')
    .replace(/^(-- SGBD:).*$/m, '$1 PostgreSQL 17 (Neon). Versão MySQL: database/01-criacao.sql');
  return `${AVISO}
-- Recria o esquema do zero (o banco do Neon já existe; não há CREATE DATABASE).
DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;
${corpo}`;
}

function converterCarga(sql) {
  const corpo = sql
    .replace(/^USE conecta_cidadao;\r?\n/m, '')
    .replace(/^SET NAMES utf8mb4;\r?\n/m, '')
    .replace(/^COMMIT;/m, () => {
      const ajustes = IDENTIDADES.map(
        ({ tabela, coluna }) =>
          `SELECT setval(pg_get_serial_sequence('${tabela}', '${coluna}'), COALESCE((SELECT MAX(${coluna}) FROM ${tabela}), 0) + 1, false);`
      ).join('\n');
      return `-- As chaves foram carregadas com o id explícito: as sequências continuam depois do maior.\n${ajustes}\n\nCOMMIT;`;
    });
  return `${AVISO}\n${corpo}`;
}

await mkdir(DESTINO, { recursive: true });
const criacao = converterCriacao(await readFile(path.join(ORIGEM, '01-criacao.sql'), 'utf8'));
const carga = converterCarga(await readFile(path.join(ORIGEM, '02-carga-dados.sql'), 'utf8'));
await writeFile(path.join(DESTINO, '01-criacao.sql'), criacao, 'utf8');
await writeFile(path.join(DESTINO, '02-carga-dados.sql'), carga, 'utf8');
console.log(
  `database/postgres: criação e carga geradas (${IDENTIDADES.length} chaves automáticas).`
);
